import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  quotaTotal: number;
  status: ProjectStatus;
}

const statusFilters: { value: ProjectStatus; label: string }[] = [
  { value: 'active', label: 'Активные' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over', label: 'Превышена квота' },
];

const statusBadgeTone: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const statusLabel: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышена квота',
};

const projects: Project[] = [
  { id: 'p1', name: 'Контекст-платформа', quotaUsed: 42, quotaTotal: 100, status: 'active' },
  { id: 'p2', name: 'Аналитика расходов', quotaUsed: 88, quotaTotal: 100, status: 'active' },
  { id: 'p3', name: 'Внутренний портал', quotaUsed: 15, quotaTotal: 100, status: 'paused' },
  { id: 'p4', name: 'Биллинг-сервис', quotaUsed: 120, quotaTotal: 100, status: 'over' },
  { id: 'p5', name: 'Мобильное приложение', quotaUsed: 60, quotaTotal: 100, status: 'active' },
  { id: 'p6', name: 'Логирование событий', quotaUsed: 30, quotaTotal: 100, status: 'paused' },
  { id: 'p7', name: 'Поисковый индекс', quotaUsed: 105, quotaTotal: 100, status: 'over' },
  { id: 'p8', name: 'Каталог продуктов', quotaUsed: 70, quotaTotal: 100, status: 'active' },
  { id: 'p9', name: 'Служба уведомлений', quotaUsed: 5, quotaTotal: 100, status: 'paused' },
  { id: 'p10', name: 'Отчёты для клиентов', quotaUsed: 95, quotaTotal: 100, status: 'active' },
  { id: 'p11', name: 'Импорт данных', quotaUsed: 130, quotaTotal: 100, status: 'over' },
  { id: 'p12', name: 'Тестовый стенд', quotaUsed: 20, quotaTotal: 100, status: 'paused' },
];

const pageSize = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return projects;
    return projects.filter((project) => activeStatuses.includes(project.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const visibleProjects = filteredProjects.slice((page - 1) * pageSize, page * pageSize);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {statusFilters.map((filter) => {
          const isActive = activeStatuses.includes(filter.value);
          return (
            <JxChip
              key={filter.value}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(filter.value)}
              onClick={() => {
                if (!isActive) toggleStatus(filter.value);
              }}
            >
              {filter.label}
            </JxChip>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Под выбранные фильтры не подошёл ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr auto auto',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 16px',
                  borderBottom: '1px solid var(--jx-border)',
                }}
              >
                <span style={{ color: 'var(--jx-text)' }}>{project.name}</span>
                <JxProgressCircle
                  value={project.quotaUsed}
                  max={project.quotaTotal}
                  showValue
                />
                <JxBadge tone={statusBadgeTone[project.status]}>
                  {statusLabel[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={page} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

